const workerTokensCSS = "/* diary · Research index palette and typography */\n:root {\n  color-scheme: dark;\n  --color-paper: light-dark(#f9f8fa, #121214);\n  --color-paper-raised: light-dark(#f1eff4, #19191d);\n  --color-paper-strong: light-dark(#eae6f0, #222226);\n  --color-ink: light-dark(#1e1b24, #f1eef4);\n  --color-ink-soft: light-dark(#494450, #cbc5d0);\n  --color-muted: light-dark(#60596a, #aaa3b0);\n  --color-rule: light-dark(#ded9e4, #2d2a31);\n  --color-rule-strong: light-dark(#8a8194, #77717f);\n  --color-accent: light-dark(#5d3c96, #c6abff);\n  --color-accent-ink: light-dark(#fff, #17121e);\n  --color-graphite: #111116;\n  --color-code-ink: #f1eef4;\n  --color-focus: var(--color-accent);\n  --color-hero-warm: light-dark(#f1e1e8, #311d26);\n  --color-hero-cool: light-dark(#e9e7fa, #1b2034);\n  --color-cover-grid: light-dark(#e5dfea, #232129);\n  --color-cover-lilac: light-dark(#7855af, #9f7dcf);\n  --color-cover-coral: light-dark(#a65264, #cf7888);\n  --color-cover-blue: light-dark(#376c99, #70a2ce);\n  --color-cover-green: light-dark(#397c6d, #63ab98);\n  --font-display: \"Geist\", \"Hiragino Sans\", \"Yu Gothic\", sans-serif;\n  --font-body: var(--font-display);\n  --font-mono: \"IBM Plex Mono\", monospace;\n  --text-xs: 0.6875rem;\n  --text-sm: 0.8125rem;\n  --text-base: 1rem;\n  --text-md: 1.25rem;\n  --text-lg: 1.5625rem;\n  --text-xl: 1.9531rem;\n  --text-2xl: 2.4414rem;\n  --text-3xl: 3.0518rem;\n  --text-4xl: 3.8147rem;\n  --text-display: clamp(1.75rem, 4.3vw + 0.85rem, 4rem);\n  --space-3xs: 0.125rem;\n  --space-2xs: 0.25rem;\n  --space-xs: 0.5rem;\n  --space-sm: 0.75rem;\n  --space-md: 1rem;\n  --space-lg: 1.5rem;\n  --space-xl: 2.5rem;\n  --space-2xl: 4rem;\n  --space-3xl: 6rem;\n  --space-4xl: 9rem;\n  --radius-control: 999px;\n  --radius-panel: 0.625rem;\n  --radius-card: 1rem;\n  --rule: 1px;\n  --dur-micro: 120ms;\n  --dur-short: 220ms;\n  --dur-long: 420ms;\n  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);\n  --ease-in: cubic-bezier(0.7, 0, 0.84, 0);\n  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);\n  --z-base: 1;\n  --z-raised: 10;\n  --z-dropdown: 100;\n  --z-sticky: 200;\n  --z-modal: 400;\n}\n\n:root[data-theme=\"light\"] { color-scheme: light; }\n:root[data-theme=\"system\"] { color-scheme: light dark; }\n"

const workerMermaidJS = "const sourceBlocks = document.querySelectorAll(\"pre > code.language-mermaid\");\n\nif (sourceBlocks.length > 0) {\n  const { default: mermaid } = await import(\"https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs\");\n  const mode = document.documentElement.dataset.theme;\n  const isDark = mode === \"system\" ? window.matchMedia(\"(prefers-color-scheme: dark)\").matches : mode !== \"light\";\n  mermaid.initialize({\n    startOnLoad: false,\n    securityLevel: \"strict\",\n    theme: isDark ? \"dark\" : \"default\",\n    flowchart: { htmlLabels: true, useMaxWidth: true },\n  });\n\n  let diagramNumber = 0;\n  for (const sourceBlock of sourceBlocks) {\n    const source = sourceBlock.textContent;\n    const diagram = document.createElement(\"div\");\n    diagram.className = \"mermaid\";\n    diagram.setAttribute(\"role\", \"img\");\n    diagram.setAttribute(\"aria-label\", \"Mermaid diagram\");\n    sourceBlock.parentElement.replaceWith(diagram);\n\n    try {\n      const { svg, bindFunctions } = await mermaid.render(`mermaid-${diagramNumber++}`, source);\n      diagram.innerHTML = svg;\n      bindFunctions?.(diagram);\n    } catch (error) {\n      console.warn(\"Could not render Mermaid diagram\", error);\n      const fallback = document.createElement(\"pre\");\n      const fallbackCode = document.createElement(\"code\");\n      fallbackCode.className = \"language-mermaid\";\n      fallbackCode.textContent = source;\n      fallback.append(fallbackCode);\n      diagram.replaceWith(fallback);\n    }\n  }\n}\n"

const workerSiteJS = "(() => {\n  const root = document.documentElement;\n  const themeToggle = document.querySelector(\"[data-theme-toggle]\");\n  const themeStorageKey = \"diary-theme\";\n  const themeModes = [\"dark\", \"light\", \"system\"];\n  const themeLabels = { system: \"自動\", light: \"ライト\", dark: \"ダーク\" };\n  const themeIcons = { system: \"◐\", light: \"☀\", dark: \"☾\" };\n  const colorScheme = window.matchMedia(\"(prefers-color-scheme: dark)\");\n  let themeMode = \"dark\";\n\n  try {\n    const storedTheme = window.localStorage.getItem(themeStorageKey);\n    if (themeModes.includes(storedTheme)) themeMode = storedTheme;\n  } catch {\n    // The theme remains usable for this page when storage is unavailable.\n  }\n\n  const effectiveTheme = () => themeMode === \"system\" ? (colorScheme.matches ? \"dark\" : \"light\") : themeMode;\n  const nextThemeMode = () => themeModes[(themeModes.indexOf(themeMode) + 1) % themeModes.length];\n  const renderTheme = () => {\n    root.dataset.theme = themeMode;\n    if (!themeToggle) return;\n\n    const nextTheme = nextThemeMode();\n    themeToggle.dataset.themeMode = themeMode;\n    themeToggle.querySelector(\"[data-theme-icon]\").textContent = themeIcons[themeMode];\n    themeToggle.querySelector(\"[data-theme-label]\").textContent = themeLabels[themeMode];\n    themeToggle.setAttribute(\"aria-pressed\", String(effectiveTheme() === \"dark\"));\n    themeToggle.setAttribute(\"aria-label\", `現在の表示テーマ: ${themeLabels[themeMode]}。${themeLabels[nextTheme]}に切り替える`);\n    themeToggle.title = `表示テーマ: ${themeLabels[themeMode]}（クリックで${themeLabels[nextTheme]}）`;\n  };\n\n  renderTheme();\n  themeToggle?.addEventListener(\"click\", () => {\n    themeMode = nextThemeMode();\n    try {\n      window.localStorage.setItem(themeStorageKey, themeMode);\n    } catch {\n      // The selected theme still applies for this page when storage is unavailable.\n    }\n    renderTheme();\n  });\n  colorScheme.addEventListener(\"change\", () => {\n    if (themeMode === \"system\") renderTheme();\n  });\n\n  const dialog = document.querySelector(\"#command-palette\");\n  const trigger = document.querySelector(\"[data-command-trigger]\");\n  const input = document.querySelector(\"#command-query\");\n  const items = Array.from(document.querySelectorAll(\"[data-command-item]\"));\n  const close = document.querySelector(\"[data-command-close]\");\n  if (!dialog || !trigger || !input || !close) return;\n\n  let activeIndex = 0;\n  const visibleItems = () => items.filter((item) => !item.hidden);\n  const setActive = (index) => {\n    const visible = visibleItems();\n    if (visible.length === 0) return;\n    activeIndex = (index + visible.length) % visible.length;\n    visible.forEach((item, itemIndex) => item.setAttribute(\"aria-selected\", String(itemIndex === activeIndex)));\n  };\n  const filter = () => {\n    const query = input.value.trim().toLocaleLowerCase();\n    items.forEach((item) => {\n      item.hidden = !item.textContent.toLocaleLowerCase().includes(query);\n    });\n    activeIndex = 0;\n    setActive(0);\n  };\n  const open = () => {\n    if (!dialog.open) dialog.showModal();\n    input.value = \"\";\n    filter();\n    input.focus({ preventScroll: true });\n  };\n  const closePalette = () => {\n    if (!dialog.open) return;\n    dialog.close();\n    trigger.focus({ preventScroll: true });\n  };\n\n  trigger.addEventListener(\"click\", open);\n  close.addEventListener(\"click\", closePalette);\n  input.addEventListener(\"input\", filter);\n  input.addEventListener(\"keydown\", (event) => {\n    if (event.key === \"ArrowDown\") {\n      event.preventDefault();\n      setActive(activeIndex + 1);\n    }\n    if (event.key === \"ArrowUp\") {\n      event.preventDefault();\n      setActive(activeIndex - 1);\n    }\n    if (event.key === \"Enter\" && input.value.trim() === \"\") {\n      const item = visibleItems()[activeIndex];\n      if (item) item.click();\n    }\n  });\n  document.addEventListener(\"keydown\", (event) => {\n    const target = event.target;\n    const isTyping = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement;\n    if ((event.metaKey || event.ctrlKey) && event.key.toLocaleLowerCase() === \"k\") {\n      event.preventDefault();\n      open();\n    }\n    if (event.key === \"/\" && !isTyping && !dialog.open) {\n      event.preventDefault();\n      open();\n    }\n    if (event.key === \"Escape\" && dialog.open) {\n      event.preventDefault();\n      closePalette();\n    }\n  });\n})();\n"
